116	// findings cursor on the first visible member of the group under the cursor.
117	func (m Model) toggleGroup() (tea.Model, tea.Cmd) {
118		if a := m.canGroup(); !a.Enabled() {
119			return m, m.footer.Warn(a.Reason)
