269	// handleGroupedKey takes the keys the grouped list answers itself. The others
270	// fall through to the results' own handling: the severity tokens, the search and
271	// the tabs drive the findings table, which the list is a view of.
272	func (m Model) handleGroupedKey(msg tea.KeyPressMsg) (tea.Model, tea.Cmd, bool) {
273		switch msg.String() {
274		case "enter":
275			next, cmd := m.openSelectedGroup()
276			return next, cmd, true
277		case keymap.Space, writeRemediationKey, keymap.Scan:
278			// They act on one finding, and a group is not one.
279			return m, m.footer.Warn(reasonOpenTheGroup), true
280		case ".", "up", "down", "pgup", "pgdown", "home", "end":
281			return m, m.groups.Update(msg), true
282		}
283		return m, nil, false
284	}
