287	// shortcuts act: the tabs, the filters and the sort belong to the list behind it.
288	func (m Model) handleGroupState(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
289		switch msg.String() {
290		case "esc":
291			return m.closeGroup()
292		case "enter":
293			f, ok := m.groupTable.Selected()
294			if !ok {
295				return m, m.footer.Warn(reasonNothingToSee)
296			}
297			return m.openDetail(f, StateGroup)
298		case keymap.Copy:
299			return m.copyGroupCommand()
300		case "up", "down", "pgup", "pgdown", "home", "end":
301			return m, m.groupTable.Update(msg)
302		}
303		return m, nil
304	}
